/**
 * @name Unsafe code evaluation via eval/exec
 * @description Using eval or exec with untrusted input can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/code-injection-eval
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module CodeInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(CodeExecution ce |
      sink = ce.getCode()
    )
  }
}

module CodeInjectionFlow = TaintTracking::Global<CodeInjectionConfig>;
import CodeInjectionFlow::PathGraph

from CodeInjectionFlow::PathNode source, CodeInjectionFlow::PathNode sink
where CodeInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Code injection from $@.", source.getNode(), "user input"

/**
 * @name Comprehensive taint tracking for cffi vulnerabilities
 * @description Check for taint flow from user input to dangerous sinks in cffi
 * @kind path-problem
 * @problem.severity error
 * @id py/cffi-comprehensive-taint
 * @tags security
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CffiConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // 1. Command injection sinks
    exists(DataFlow::CallCfgNode call |
      (
        // System command execution
        call = API::builtin("system").getACall() or
        call = API::moduleImport("subprocess").getMember(["call", "check_call", "check_output", "run", "Popen"]).getACall() or
        call = API::moduleImport("os").getMember("popen").getACall() or
        call = API::moduleImport("os").getMember("popen2").getACall() or
        call = API::moduleImport("os").getMember("popen3").getACall() or
        call = API::moduleImport("os").getMember("popen4").getACall()
      ) and
      sink = call.getArg(0)
    ) or
    // 2. Code injection sinks
    exists(DataFlow::CallCfgNode call |
      (
        call = API::builtin("eval").getACall() or
        call = API::builtin("exec").getACall() or
        call = API::builtin("compile").getACall() or
        call = API::moduleImport("builtins").getMember("eval").getACall() or
        call = API::moduleImport("builtins").getMember("exec").getACall() or
        call = API::moduleImport("builtins").getMember("compile").getACall()
      ) and
      sink = call.getArg(0)
    ) or
    // 3. File system sinks (path traversal)
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("os").getMember(["open", "remove", "unlink", "rmdir", "mkdir", "makedirs", "rename", "chmod", "chown"]).getACall() or
        call = API::moduleImport("shutil").getMember(["copy", "copyfile", "copytree", "move", "rmtree"]).getACall() or
        call = API::builtin("open").getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module CffiFlow = TaintTracking::Global<CffiConfig>;
import CffiFlow::PathGraph

from CffiFlow::PathNode source, CffiFlow::PathNode sink
where CffiFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential vulnerability: user input reaches dangerous sink $@.", source.getNode(), "user input"
